"""Error classification and transparent local plan fallback."""
def classify_error(exc):
    text = (str(exc) + " " + exc.__class__.__name__).lower()
    if any(x in text for x in ("401", "403", "api key", "unauthorized", "authentication", "permission denied")): return "auth"
    if "429" in text or "quota" in text or "resource_exhausted" in text: return "quota"
    if any(x in text for x in ("timeout", "timed out")): return "timeout"
    if any(x in text for x in ("404", "not found", "unsupported model", "model not found")): return "model"
    if any(x in text for x in ("safety", "blocked", "refusal")): return "safety"
    if any(x in text for x in ("connection", "network", "temporarily unavailable", "503", "502", "500")): return "temporary"
    return "unknown"

def local_fallback_plan(intake, metrics=None, evidence=None):
    minutes = max(5, int(intake.get("available_minutes", 30)))
    task = (intake.get("task") or "your priority task").strip() or "your priority task"
    setup=min(3, minutes-2); review=max(1, round(minutes*0.15)); work=max(1, minutes-setup-review)
    evidence=evidence or []
    return {"summary":f"A local plan for {task}, based only on the details you entered. This was not generated by Gemini.","steps":[{"title":"Define the next visible outcome","minutes":setup,"rationale":"Write one concrete result to aim for before starting."},{"title":"Work in one protected block","minutes":work,"rationale":"Keep the task and its required materials open; silence optional alerts."},{"title":"Review and choose the next step","minutes":review,"rationale":"Note progress and make the next action explicit."}],"environment_changes":["Place the phone out of reach or enable Do Not Disturb.","Keep only task-relevant tabs and materials open."],"if_interrupted":"Write down the interruption, return to the last visible task step, and restart with a two-minute commitment.","evidence_ids":[x["id"] for x in evidence[:3]],"source":"local"}
